  'bb2eb736-2720-5649-b1ca-21a3e2d90799', '150513ad-471e-5c6c-95ef-1f45082fb5f1',
  'Given an array which the elements in it are random. Now we want to build a Max heap from this array. Implement functions Reheap up and Reheap down to heapify element at index position. We will use it to build a heap in next question.

To keep things simple, this question will separate the heap array, not store it in the class heap.

```cpp
void reheapDown(int maxHeap[], int numberOfElements, int index);
void reheapUp(int maxHeap[], int numberOfElements, int index);
```

**For example:**

| Test | Result |
| :--- | :--- |
| ```cpp
int arr[] = {1,2,3,4,5,6,7,8};
int size = sizeof(arr)/sizeof(arr[0]);
reheapDown(arr,size,0);
cout << "[ ";
for(int i=0;i<size;i++)
    cout << arr[i] << " ";
cout << "]";
``` | `[ 3 2 7 4 5 6 1 8 ]` |
| ```cpp
int arr[] = {1,2,3,4,5,6,7,8};
int size = sizeof(arr)/sizeof(arr[0]);
reheapUp(arr,size,7);
cout << "[ ";
for(int i=0;i<size;i++)
    cout << arr[i] << " ";
cout << "]";
``` | `[ 8 1 3 2 5 6 7 4 ]` |

Đáp án: ```cpp
void reheapDown(int maxHeap[], int numberOfElements, int index)
{
    int maxIndex = -1;
    int left = index*2 + 1;
    int right = index*2 + 2;

    if (left < numberOfElements)
    {
        if (maxHeap[index] < maxHeap[left] )
        {
            maxIndex = left;
        }
    }
    if (right < numberOfElements)
    {
    if (maxHeap[(maxIndex == -1 ? index : maxIndex)] < maxHeap[right])
    {
        maxIndex = right;
    }
    }
    if (maxIndex == -1)
        return;
    swap(maxHeap[index], maxHeap[maxIndex]);
    reheapDown( maxHeap,  numberOfElements, maxIndex);
}

void reheapUp(int maxHeap[], int numberOfElements, int index)
{
    if (index != 0)
    {
        int parent = (index-1)/2;
        if (maxHeap[index] > maxHeap[parent])
        {
            swap(maxHeap[index],maxHeap[parent]);
            reheapUp(maxHeap,numberOfElements,parent);
        }
    }
}
```', 1
);

