Đáp án: ```cpp
template<class T>
int Heap<T>::getItem(T item) {
    if (count == 0) return -1;
    for (int i = 0; i < count; ++i)
    {
        if (this->elements[i] == item) return i;
    }
    return -1;
}

template<class T>
void Heap<T>::remove(T item) {
    int pos = getItem(item);
    if (pos == -1) return;
    swap(this->elements[pos], this->elements[count-1]);
    count = count - 1;
    reheapDown(pos);
}

template<class T>
void Heap<T>::clear() {
    if (this->elements != nullptr)
    {
        delete[]elements;
        elements = nullptr;
        this->capacity = 0;
        this->count = 0;
    }
}
```', 2
